  function cleanSourceLine(value) {
    return String(value||'').replace(/\u00a0/g,' ').replace(/[ \t]{2,}/g,' ').trim()
      .replace(/\bфин\.?\s*модель\b/gi,'Финансовая модель')
      .replace(/\bсмр\b/gi,'СМР')
      .replace(/\bзам\.?\s*дир\.?\s*[-–—]\s*ги\b/gi,'Заместитель директора — главный инженер')
      .replace(/\bзам\.?\s*дир\.?\b/gi,'Заместитель директора')
      .replace(/\bги\b/gi,'Главный инженер');
  }
  function isHiddenContactLine(value) { return /(?:^|[:—-]\s*)\[контакт скрыт\]\s*$/i.test(String(value||'').trim()); }
  function richText(value) {
    const lines=esc(String(value||'').replace(/<br\s*\/?\s*>/gi,'\n')).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\`(.+?)\`/g, '<code>$1</code>')
      .split('\n').map(line=>cleanSourceLine(line.replace(/\s*\|\s*$/,'').trim())).filter(line=>line&&line!=='|'&&!isHiddenContactLine(line));
    const blocks=[], bullets=[];
    const flushBullets=()=>{if(bullets.length){blocks.push(`<ul>${bullets.map(item=>`<li>${item}</li>`).join('')}</ul>`);bullets.length=0;}};
    lines.forEach(line=>{
      if(/^[-✔•]\s*/.test(line)){bullets.push(line.replace(/^[-✔•]\s*/,''));return;}
      flushBullets();
      if(line.length>5 && /[А-ЯЁ]/.test(line) && line===line.toUpperCase()) blocks.push(`<h3>${line}</h3>`);
      else blocks.push(`<p>${line}</p>`);
    });
    flushBullets();
    return blocks.join('');
  }
  function sheetTable(lines) {
    const rows={};
    lines.forEach(line=>{
      const cells=line.split('|').slice(1,-1).map(cell=>cell.trim());
      if(cells.length<2 || /^[- ]+$/.test(cells[0])) return;
      const cell=/^([A-Z]+)(\d+)$/.exec(cells[0]);
      if(!cell) return;
      const row=cell[2], column=cell[1];
      (rows[row]||(rows[row]={}))[column]=cells.slice(1).join(' | ').replace(/\s*\|\s*$/,'').trim();
    });
    const ordered=Object.entries(rows).sort((a,b)=>Number(a[0])-Number(b[0]));
    if(!ordered.length) return standardTable(lines);
    return `<div class="course-sheet">${ordered.map(([number,columns])=>{
      const label=(columns.A||'').trim(), content=Object.entries(columns).filter(([column])=>column!=='A').map(([,value])=>value).filter(Boolean).join('\n');
      if(!label && !content) return '';
      if(/^(категория|наименование|вид работ)$/i.test(label)||/^(информация|значение)$/i.test(content)) return '';
      if(label && !content && label===label.toUpperCase() && label.length>4) return `<h3 class="course-sheet-title">${esc(label)}</h3>`;
      const normalized=value=>String(value||'').toLocaleLowerCase('ru').replace(/[^а-яёa-z0-9]+/g,'');
      if(!content || normalized(content).length<3 || normalized(content)===normalized(label)) return '';
      const title=label || `Рабочий блок ${number}`;
      return `<details class="course-topic" ${Number(number)<5?'open':''}><summary><span>${esc(title)}</span><b>Открыть</b></summary><div class="course-topic-body">${richText(content||label)}</div></details>`;
    }).join('')}</div>`;
  }
  function inlineTableText(value) {
    return esc(String(value||'').trim())
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      .replace(/`(.+?)`/g, '<code>$1</code>')
      .replace(/<br\s*\/?\s*>/gi, '<br>');
  }
  function standardTable(lines) {
    const rows=lines.map(line=>line.trim().replace(/^\||\|$/g,'').split('|').map(cell=>cell.trim()));
    if(!rows.length) return '';
    const separator=row=>row.length&&row.every(cell=>/^:?-{3,}:?$/.test(cell.replace(/\s/g,'')));
    const header=rows[0], body=separator(rows[1]||[])?rows.slice(2):rows.slice(1);
    if(!header.length||!body.length) return '';
    return `<div class="course-table-wrap"><table class="course-table"><thead><tr>${header.map(cell=>`<th>${inlineTableText(cell)}</th>`).join('')}</tr></thead><tbody>${body.filter(row=>row.some(cell=>cell)).map(row=>`<tr>${header.map((_,index)=>`<td>${inlineTableText(row[index]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }
  function flowDiagram(lines) {
    const steps=lines.flatMap(line=>String(line||'').split(/\s*(?:→|↓)\s*/)).map(step=>step.trim()).filter(Boolean);
    if(!steps.length) return '';
    return `<ol class="course-flow" aria-label="Схема процесса">${steps.map((step,index)=>`<li class="course-flow-step"><b>${String(index+1).padStart(2,'0')}</b><span>${esc(step)}</span></li>`).join('')}</ol>`;
  }
  function courseImage(alt, src) {
    const normalized=String(src||'').replace(/^\//,'');
    if(!/^media\/[a-z0-9._-]+\.(?:png|jpe?g|webp)$/i.test(normalized))return '';
    return `<figure class="course-figure"><img src="/${esc(normalized)}" alt="${esc(String(alt||'').slice(0,180))}" loading="lazy"><figcaption class="course-figure-caption">${esc(alt)}</figcaption></figure>`;
  }
  function markdown(raw) {
    const text=String(raw||'').replace(/^---[\s\S]*?---\s*/, '').replace(/## Первичный источник\s*[\s\S]*?(?=## Пол(?:ное содержимое|ный текст) из источника)/, '').replace(/^> Полный структурированный экспорт[^\n]*\n?/gm, '').replace(/^\[Открыть[^\n]*\]\([^\n]*\)\s*$/gm, '').replace(/\[\[([^\]|]+)\|([^\]]+)\]\]/g,'$2').replace(/\[\[([^\]]+)\]\]/g,'$1').replace(/\r/g,'');
    const lines=text.split('\n'), output=[];
    for(let index=0;index<lines.length;){
      if(/^:::flow\s*$/i.test(lines[index].trim())){const flow=[];index+=1;while(index<lines.length&&!/^:::\s*$/.test(lines[index].trim()))flow.push(lines[index++]);if(index<lines.length)index+=1;output.push(flowDiagram(flow));continue;}
      // Spreadsheet and Google Docs exports often use a fenced `text` block
      // for a process diagram.  Treat it as a diagram, not as a literal
      // fragment (which was why users saw “`text” in ISO 37001).
      if(/^```(?:text|plaintext|md|markdown)?\s*$/i.test(lines[index].trim())){const block=[];index+=1;while(index<lines.length&&!/^```\s*$/.test(lines[index].trim()))block.push(lines[index++]);if(index<lines.length)index+=1;output.push(block.some(line=>/[→↓]/.test(line))?flowDiagram(block):`<pre>${esc(block.join('\n'))}</pre>`);continue;}
      if(/^\|/.test(lines[index])){const table=[];while(index<lines.length&&/^\|/.test(lines[index]))table.push(lines[index++]);output.push(sheetTable(table));continue;}
      const image=/^!\[([^\]]*)\]\(([^)]+)\)\s*$/.exec(lines[index].trim());if(image){index+=1;output.push(courseImage(image[1],image[2]));continue;}
      const line=cleanSourceLine(lines[index++]); if(!line||isHiddenContactLine(line)||/^#{0,3}\s*(первичный источник|полное содержимое из источника|полный текст из источника)$/i.test(line)||/^(направляю|направляем)\s+актуальн\w*\s+форм\w*/i.test(line)) continue;
      const headingMatch=/^(#{1,6})\s+(.+)$/.exec(line);
      if(headingMatch){
        const level=headingMatch[1].length;
        const heading=headingMatch[2].replace(/^Лист:\s*/,'');
        const tag=level===1?'h2':'h3';
        const className=level===1?'course-document-title':'course-section-heading';
        output.push(`<${tag} class="${className}">${esc(heading)}</${tag}>`);
        continue;
      }
      const numbered=/^(\d+)[.)]\s+(.+)$/.exec(line);
      if(numbered){
        const items=[numbered];
        while(index<lines.length){
          const next=cleanSourceLine(lines[index]);
          const nextNumbered=/^(\d+)[.)]\s+(.+)$/.exec(next);
          if(!nextNumbered)break;
          items.push(nextNumbered);index+=1;
        }
        output.push(`<ol class="course-number-list">${items.map(([,number,text])=>`<li><b>${esc(number)}</b><span>${richText(text)}</span></li>`).join('')}</ol>`);
        continue;
      }
      output.push(`<div class="course-prose">${richText(line)}</div>`);
    }
    return output.join('');
  }
  function readableDocument(data, path, reference=false) {
    if (data?.format==='html') return safeRichHtml(data.content);
    // Passports come from spreadsheet exports.  Their rows must be grouped
    // into labelled, collapsible sections instead of appearing as a long
    // unstructured dump with blank gaps.
    if (reference && typeof window.renderEducationDocument==='function') {
      return window.renderEducationDocument(String(data?.content||''), sourceTitle(path));
    }
    return markdown(data?.content||'');
  }
  function chatText(value) { return esc(value).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br>'); }
