  function reader(){
    const course=current();if(!course)return catalog();
    const role=access?.role||state.role,trainee=role==='trainee';
    if(trainee)return readerTraineeLegacy(course);
    if(course.id==='contacts')return contactsReader(course);
    const audience=activeAudience(),workspace=workspaceFor(course,audience),indexes=sourceIndexesForAudience(course,audience),selected=selectedSourceFor(course),path=selected.path,completed=done(course),inlineEditing=canEditBase()&&state.inlineEditorPath===path;
    const sourceButtons=indexes.map(index=>`<button type="button" class="${index===selected.index?'active':''}" aria-current="${index===selected.index?'page':'false'}" onclick="academySource(${index})"><span>${String(index+1).padStart(2,'0')}</span><b>${esc(sourceTitle(course.sources[index]))}</b></button>`).join('');
    const flow=workspace.flow.map((item,index)=>`<li><b>${String(index+1).padStart(2,'0')}</b><span>${esc(item)}</span></li>`).join('');
    const list=items=>`<ul>${items.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`;
    const documentPane=path?(inlineEditing?inlineMaterialEditor(course,path):`<section class="workspace-source" id="workspace-source"><div><h2>${esc(sourceTitle(path))}</h2><p>Полный материал для сверки деталей по текущему рабочему виду.</p></div><div id="course-document" class="course-document"><div class="course-loading"><b>Открываю материал…</b><span>Текст, таблицы и чек-листы загрузятся здесь.</span></div></div></section>`):'';
    const editAction=canEditBase()?`<button class="reader-edit" onclick="academyEditOpenedMaterial()" ${path?'':'disabled'}>✎ Редактировать текст</button><button class="reader-edit" onclick="academyEditTile('${course.id}')">⊕ Материалы плитки</button>`:'';
    const authored=course.content?`<section class="workspace-source custom-tile-document">${safeRichHtml(course.content)}</section>`:'';
    const roleFocus=audience==='manager'?['Фокус менеджера','Диагностика запроса, польза для клиента, КП и конкретный следующий контакт.']:['Фокус эксперта','Проверка входных данных, подготовка, контроль и подтверждённый результат.'];
    const detailedManagerFlow=audience==='manager'?`<section class="workspace-source expert-passport-workflow" id="workspace-flow"><div><h2>Ход работы менеджера</h2><p>Полные регламенты, алгоритмы и скрипты из подключённых материалов. Открывайте нужный этап — это не сокращённая памятка.</p></div><div id="manager-detailed-flow" class="expert-passport-flow"><div class="course-loading"><b>Загружаю рабочие материалы менеджера…</b><span>Откроются подробные алгоритмы, таблицы и чек-листы.</span></div></div></section>`:'';
    const detailedExpertFlow=audience==='expert'?`<section class="workspace-source expert-passport-workflow" id="workspace-passport-flow"><div><h2>Подробный ход работы из паспортов</h2><p>Этапы ниже извлечены из листов «Ход работы эксперта» по каждому продукту.</p></div><div id="expert-passport-flow" class="expert-passport-flow"><div class="course-loading"><b>Загружаю этапы из паспортов…</b><span>Откроются подробные таблицы и чек-листы.</span></div></div></section>`:'';
    const primaryFlow=audience==='manager'?'':`<section class="workspace-block workspace-flow" id="workspace-flow"><h2>Ход работы</h2><ol>${flow}</ol></section>`;
    return shell(`<button class="course-back" onclick="academyCatalog()">← К плиткам</button><header class="reader-head"><div><span>${esc(course.eyebrow||'РАБОЧАЯ ТЕМА')}</span><h1><i>${course.icon}</i>${esc(course.title)}</h1><p>${audience==='manager'?'Версия для менеджера: диагностика, ценность, КП и следующий контакт.':'Версия для эксперта: проверка, подготовка, контроль и результат.'}</p></div><div class="reader-actions">${editAction}<button class="reader-presentation" onclick="academyPresentation('${course.id}')">Открыть презентацию</button><button class="reader-test" onclick="academyTest('${course.id}')">Открыть практику</button><button class="reader-complete ${completed?'is-done':''}" onclick="academyComplete('${course.id}')">${completed?'✓ Изучено':'Отметить изученным'}</button></div></header>${staffModeControl()}<section class="reader-layout role-reader-layout"><aside class="reader-outline"><b>Содержание плитки</b><p>Рабочая структура для роли «${audienceLabel(audience)}».</p><a href="#workspace-concept">Понятие</a><a href="#workspace-people">Специалисты</a><a href="#workspace-tools">Инструменты</a><a href="#workspace-flow">Ход работы</a>${audience==='expert'?'<a href="#workspace-passport-flow">Подробный ход работы</a>':''}${indexes.length?`<details class="workspace-source-list"><summary>Полные материалы · ${indexes.length}</summary>${sourceButtons}</details>`:''}<div class="reader-practice"><span>После чтения</span><b>Закрепите логику на кейсе по этой роли.</b><button type="button" onclick="academyTest('${course.id}')">Открыть практику →</button></div></aside><article class="reader-content role-reader-content"><section class="workspace-intro"><span>${audience==='manager'?'МЕНЕДЖЕР':'ЭКСПЕРТ'}</span><h2>${roleFocus[0]}</h2><p>${roleFocus[1]}</p></section><section class="workspace-block" id="workspace-concept"><h2>Понятие</h2><p>${esc(workspace.concept)}</p></section><section class="workspace-block" id="workspace-people"><h2>Специалисты</h2>${list(workspace.people)}</section><section class="workspace-block" id="workspace-tools"><h2>Инструменты и документы</h2>${list(workspace.tools)}</section>${primaryFlow}${detailedManagerFlow}${detailedExpertFlow}${gpnContacts(course)}${tileAttachmentsReader(course)}${authored}${documentPane}<div class="reader-bottom"><button class="reader-complete ${completed?'is-done':''}" onclick="academyComplete('${course.id}')">${completed?'✓ Плитка изучена':'✓ Я изучил(а) эту плитку'}</button><button class="reader-test" onclick="academyTest('${course.id}')">Открыть практику →</button></div></article></section>`);
  }
  function tileAttachmentsEditor(tile,custom){
    const items=tileAttachments(tile), attachmentRows=items.length?`<div class="library-attachment-chips">${items.map((item,index)=>`<span><i>${attachmentIcon(item.kind)}</i>${esc(ATTACHMENT_TYPES[item.kind])}: ${esc(item.title)}<button type="button" aria-label="Убрать ${esc(item.title)}" onclick="academyRemoveLibraryAttachment('${esc(tile.id)}',${custom},${index})">×</button></span>`).join('')}</div>`:'<p class="library-no-sources">Внешних материалов пока нет.</p>';
    return `<section class="library-attachment-manager"><div><b>Внешние материалы</b><p>Добавьте ссылку на видео, Google-таблицу, презентацию, документ или файл в облаке. Ссылка будет видна прямо в этой плитке.</p></div>${attachmentRows}<div class="library-attachment-add"><label>Название<input data-attachment-title placeholder="Например, Прайс 2026"></label><label>Тип<select data-attachment-kind>${Object.entries(ATTACHMENT_TYPES).map(([kind,label])=>`<option value="${kind}">${label}</option>`).join('')}</select></label><label class="library-attachment-url">Ссылка<input data-attachment-url type="url" inputmode="url" placeholder="https://…"></label><button class="reader-complete" type="button" onclick="academyAddLibraryAttachment('${esc(tile.id)}',${custom})">＋ Добавить ссылку</button></div></section>`;
  }
  function libraryTileEditor(tile,sources){
    const isDraft=!isPublishedLibraryTile(tile), selected=tile.sources||[], available=sources.filter(path=>!selected.includes(path));
    const materialChips=selected.length?`<div class="library-source-chips">${selected.map(path=>`<span>${esc(sourceTitle(path))}<button type="button" aria-label="Убрать материал ${esc(sourceTitle(path))}" onclick="academyRemoveLibrarySource('${esc(tile.id)}','${encodeURIComponent(path)}')">×</button></span>`).join('')}</div>`:'<p class="library-no-sources">Материалов пока нет. Это нормально: можно написать свой текст или добавить источник ниже.</p>';
    return `<article class="library-custom-tile ${isDraft?'is-draft':''}" data-library-tile="${esc(tile.id)}"><div class="tile-editor-head"><div><b>${isDraft?'Черновик · не виден сотрудникам':'Созданная плитка'}</b><small>${isDraft?'Заполните только то, что нужно для этой темы.':'Видна менеджеру, эксперту и руководителю.'}</small></div><button class="reader-complete danger" type="button" onclick="academyRemoveLibraryTile('${esc(tile.id)}',true)">Удалить в корзину</button></div><div class="library-tile-fields"><label>Название<input data-library-field="title" value="${esc(tile.title||'')}" placeholder="Например, Регламент партнёров"></label><label>Раздел<input data-library-field="eyebrow" value="${esc(tile.eyebrow||'')}" placeholder="Например, Продажи"></label></div><label>Краткое описание<textarea data-library-field="lead" placeholder="Кому и зачем нужен этот материал.">${esc(tile.lead||'')}</textarea></label><section class="library-source-manager"><div><b>Подключённые материалы</b><p>Добавляйте материалы из базы по одному. Удаление здесь не удаляет сам документ из базы.</p></div>${materialChips}<label class="library-source-add">Добавить материал<select onchange="academyAddLibrarySource('${esc(tile.id)}',this.value)"><option value="">Выберите материал…</option>${available.map(path=>`<option value="${esc(path)}">${esc(sourceTitle(path))}</option>`).join('')}</select></label></section>${tileAttachmentsEditor(tile,true)}<section class="library-own-text"><div><b>Собственный текст плитки</b><p>Необязательно подключать документ: напишите инструкцию прямо здесь и оформите её как в Word.</p></div><div class="rich-editor-toolbar" aria-label="Форматирование текста плитки"><button type="button" onmousedown="event.preventDefault();academyFormatText('bold')"><b>Ж</b></button><button type="button" onmousedown="event.preventDefault();academyFormatText('italic')"><i>К</i></button><button type="button" onmousedown="event.preventDefault();academyFormatText('underline')"><u>Ч</u></button><button type="button" onmousedown="event.preventDefault();academyFormatText('insertUnorderedList')">• Список</button><button type="button" onmousedown="event.preventDefault();academyFormatText('formatBlock','h3')">Заголовок</button><input aria-label="Цвет выделенного текста" type="color" value="#087f76" oninput="academyFormatText('foreColor',this.value)"></div><div class="rich-editor library-rich-editor" contenteditable="true" data-library-field="content" data-placeholder="Напишите учебный текст, добавьте этапы, таблицу или чек-лист…">${safeRichHtml(tile.content||'')}</div></section></article>`;
  }
  function libraryStockTileEditor(tile){return `<article data-library-tile="${esc(tile.id)}"><div class="tile-editor-head"><div><b>Готовая плитка</b><small>Исходные материалы закреплены в учебной структуре.</small></div><button class="reader-complete danger" type="button" onclick="academyRemoveLibraryTile('${esc(tile.id)}',false)">Убрать в корзину</button></div><label>Название<input data-library-field="title" value="${esc(tile.title)}"></label><label>Раздел<input data-library-field="eyebrow" value="${esc(tile.eyebrow)}"></label><label>Описание<textarea data-library-field="lead">${esc(tile.lead)}</textarea></label><small>${tile.sources.length} подключённых материалов. Дополнительные видео, таблицы, презентации и файлы добавляются ниже.</small>${tileAttachmentsEditor(tile,false)}</article>`;}
  const editableSources=()=>[...new Set([...baseLibraryCourses().flatMap(course=>course.sources),...FULL_LIBRARY_EXTRA_SOURCES,...state.librarySourcePaths])];
  function sourceEditor(){const paths=editableSources(),path=state.sourceEditorPath||paths[0]||'';return shell(`<button class="course-back" onclick="academyCatalog()">← Все обучения</button><section class="leader-results curriculum-editor"><span>РУКОВОДИТЕЛЬ · РЕДАКТОР БАЗЫ ЗНАНИЙ</span><h1>Редактор материалов</h1><p>Ниже — исходные материалы, а не плитки каталога. Ищите по названию и открывайте нужный документ: поле не перерисовывается при наборе, поэтому курсор остаётся на месте.</p><label>Найти материал<input class="academy-source-search" placeholder="Например: МЧС, металл, договор…" oninput="academyFilterSourceEditor(this)"></label><div class="academy-source-picker" aria-label="Исходные материалы">${paths.map(item=>`<button type="button" data-source-picker="${esc((sourceTitle(item)+' '+item).toLocaleLowerCase('ru'))}" class="${item===path?'active':''}" onclick="academySelectSourceEditor('${esc(item)}')"><small>${esc(item.split('/')[0])}</small><b>${esc(sourceTitle(item))}</b></button>`).join('')}</div><div class="rich-editor-toolbar" aria-label="Форматирование текста"><button type="button" onmousedown="event.preventDefault();academyFormatText('bold')"><b>Ж</b></button><button type="button" onmousedown="event.preventDefault();academyFormatText('italic')"><i>К</i></button><button type="button" onmousedown="event.preventDefault();academyFormatText('underline')"><u>Ч</u></button><button type="button" onmousedown="event.preventDefault();academyFormatText('insertUnorderedList')">• Список</button><button type="button" onmousedown="event.preventDefault();academyFormatText('formatBlock','h3')">Заголовок</button><input aria-label="Цвет выделенного текста" type="color" value="#087f76" oninput="academyFormatText('foreColor',this.value)"></div><div id="source-rich-editor" class="rich-editor source-rich-editor" contenteditable="true">${state.sourceEditorLoading?'<p>Загружаю материал…</p>':safeRichHtml(state.sourceEditorHtml)}</div><div class="editor-actions"><button class="reader-test" ${state.sourceEditorSaving||state.sourceEditorLoading?'disabled':''} onclick="academySaveSourceEditor()">${state.sourceEditorSaving?'Сохраняю…':'Сохранить материал'}</button></div>${state.sourceEditorError?`<p class="exam-error">${esc(state.sourceEditorError)}</p>`:''}</section>`)}
  function bindLibraryAutosave(){const editor=document.querySelector('.curriculum-editor');if(!editor)return;const queue=event=>{if(event.target?.matches('[data-library-field]'))window.academyQueueLibrarySave();};editor.oninput=queue;editor.onchange=queue;}
  function render() { if (!access) { state.login=true; el.innerHTML=loginLanding(); return; } state.login=false; el.innerHTML = state.page === 'course' ? reader() : state.page === 'presentation' ? presentation() : state.page === 'exam' ? finalExam() : state.page === 'test-hub' ? testHub() : state.page === 'leader-results' ? leaderResults() : state.page === 'curriculum-editor' ? curriculumEditor() : state.page === 'library-editor' ? libraryEditor() : state.page === 'source-editor' ? sourceEditor() : state.page === 'governance' ? governance() : catalog(); if (state.page==='library-editor') bindLibraryAutosave(); if (state.page==='leader-results') injectLeaderOperationalPanel(); if (state.page==='course'){loadDocument();loadManagerDetailedWorkflow();loadExpertPassportWorkflow();} if (state.page==='presentation') loadPresentationDocument(); }
  async function academySaveError(response,fallback){const body=await response.json().catch(()=>({}));if(body.error==='persistent_storage_not_configured')return 'Постоянное хранилище ещё не подключено: материал не сохранён.';if(body.error==='persistent_storage_unavailable')return 'Постоянное хранилище временно недоступно: материал не сохранён. Повторите позже.';return fallback;}
  window.academyEditOpenedMaterial=()=>{if(!canEditBase())return;const course=current(),{path}=selectedSourceFor(course);if(!path)return;state.inlineEditorPath=path;state.inlineEditorHtml='';state.inlineEditorError='';academyLoadInlineMaterial();render();};
  window.academyCloseInlineEditor=()=>{state.inlineEditorPath='';state.inlineEditorHtml='';state.inlineEditorError='';state.inlineEditorLoading=false;state.inlineEditorSaving=false;render();};
  window.academyLoadInlineMaterial=async()=>{const path=state.inlineEditorPath,course=current();if(!path||!course)return;state.inlineEditorLoading=true;state.inlineEditorError='';render();try{const response=await fetch(courseDocumentUrl(course,path),{headers:authHeaders()});if(!response.ok)throw new Error('Не удалось загрузить материал для редактирования.');const data=await response.json();state.inlineEditorHtml=data.format==='html'?safeRichHtml(data.content):markdown(data.content);}catch(error){state.inlineEditorError=error.message||'Не удалось загрузить материал для редактирования.';}state.inlineEditorLoading=false;render();};
  window.academySaveInlineMaterial=async(path,courseId)=>{if(!canEditBase())return;const content=safeRichHtml(document.getElementById('inline-rich-editor')?.innerHTML||''),title=document.getElementById('inline-course-title')?.value.trim()||'',eyebrow=document.getElementById('inline-course-eyebrow')?.value.trim()||'',lead=document.getElementById('inline-course-lead')?.value.trim()||'',course=current();if(!content.trim()){state.inlineEditorError='Материал не может быть пустым.';return render();}if(!title||!eyebrow||!lead){state.inlineEditorError='Заполните название, раздел и краткое описание плитки.';return render();}state.inlineEditorSaving=true;state.inlineEditorError='';render();let textSaved=false;try{const materialResponse=await fetch('/api/academy/document-overrides',{method:'POST',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({path,content})});if(!materialResponse.ok)throw new Error(await academySaveError(materialResponse,'Не удалось сохранить текст материала.'));textSaved=true;const metaChanged=title!==course.title||eyebrow!==course.eyebrow||lead!==course.lead;if(metaChanged){const catalog=state.libraryCatalog||{hidden:[],overrides:{},custom:[]};catalog.hidden=catalog.hidden||[];catalog.overrides=catalog.overrides||{};catalog.custom=catalog.custom||[];const custom=catalog.custom.find(item=>item.id===courseId);if(custom)Object.assign(custom,{title,eyebrow,lead});else catalog.overrides[courseId]={...(catalog.overrides[courseId]||{}),title,eyebrow,lead};state.libraryCatalog=catalog;const catalogResponse=await fetch('/api/academy/library-catalog',{method:'POST',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify(catalog)});if(!catalogResponse.ok)throw new Error(await academySaveError(catalogResponse,'Текст сохранён, но изменить карточку не удалось.'));const catalogData=await catalogResponse.json();state.libraryCatalog=catalogData.catalog||catalog;}state.inlineEditorHtml=content;state.inlineEditorError='Изменения сохранены. Их уже увидят сотрудники при следующем открытии плитки.';}catch(error){state.inlineEditorError=textSaved?'Текст сохранён, но карточка не обновлена: '+(error.message||'повторите сохранение.'):error.message||'Не удалось сохранить изменения.';}state.inlineEditorSaving=false;render();};
  async function loadDocument() {
    const course=current(); if (!course || !access) return;
    const {index,path}=selectedSourceFor(course), requestId=++state.documentRequestId;
    if(state.inlineEditorPath===path)return;
    const target=document.getElementById('course-document'); if (!target) return;
    if(course.content&&!(course.sources||[]).length){target.innerHTML=safeRichHtml(course.content);return;}
    const isCurrent=()=>requestId===state.documentRequestId&&state.page==='course'&&state.course===course.id&&state.tab===index;
    try { const response=await fetch(courseDocumentUrl(course,path),{headers:authHeaders()}); if(response.status===401){ state.login=true; access=null; sessionStorage.removeItem(accessKey); return render(); } if(!response.ok) throw Error(`Код ${response.status}`); const data=await response.json(); if(isCurrent()) { const currentTarget=document.getElementById('course-document'); if(currentTarget) currentTarget.innerHTML=readableDocument(data,path,state.referenceView); } }
    catch (error) { if(isCurrent()) { const currentTarget=document.getElementById('course-document'), fallback=String(course.fallbackContent||'').trim(), fallbackHtml=fallback?(fallback.includes('<')?safeRichHtml(fallback):markdown(fallback)):''; if(currentTarget) currentTarget.innerHTML=`<div class="course-error"><b>Материал временно недоступен.</b><span>Раздел «${esc(sourceTitle(path))}»: ${esc(error.message||'неизвестная ошибка')}. Попробуйте загрузить ещё раз.</span><button onclick="academyReloadCourse()">Загрузить снова</button></div>${fallbackHtml?`<section class="course-document course-fallback"><h3>Краткий резервный материал</h3>${fallbackHtml}</section>`:''}`; } }
  }
  async function loadPresentationDocument() {
    const course=current(), sourceIndex=state.presentationSlide-2;
    if(!course||!access||sourceIndex<0||!course.sources[sourceIndex])return;
    const path=course.sources[sourceIndex],requestId=++state.presentationRequestId,target=document.getElementById('presentation-document');
    if(!target)return;
    const isCurrent=()=>requestId===state.presentationRequestId&&state.page==='presentation'&&state.course===course.id&&state.presentationSlide-2===sourceIndex;
    try { const response=await fetch(courseDocumentUrl(course,path),{headers:authHeaders()});if(response.status===401){state.login=true;access=null;sessionStorage.removeItem(accessKey);return render();}if(!response.ok)throw Error();const data=await response.json();if(isCurrent()){const currentTarget=document.getElementById('presentation-document');if(currentTarget)currentTarget.innerHTML=readableDocument(data,path,isReferenceMaterial(path));} }
    catch (_) { if(isCurrent()){const currentTarget=document.getElementById('presentation-document');if(currentTarget)currentTarget.innerHTML='<div class="course-error"><b>Не удалось открыть этот слайд.</b><span>Проверьте соединение и повторите загрузку.</span><button onclick="academyReloadPresentationSlide()">Загрузить снова</button></div>';} }
  }
  window.academyCatalog=()=>{state.page='catalog';state.course='';state.test=false;render();window.scrollTo(0,0);};
  window.academyTestHub=()=>{if(!canEditBase())return;state.page='test-hub';state.course='';state.test=false;render();window.scrollTo(0,0);};
  const renderCatalogSearch=()=>{render();requestAnimationFrame(()=>{const input=document.querySelector('.academy-tile-search');if(!input)return;input.focus();input.setSelectionRange(input.value.length,input.value.length);});};
  window.academySearchTiles=value=>{state.catalogQuery=value;state.catalogMatches=[];state.catalogSearchResults=[];state.catalogSearching=false;const query=value.trim(),requestId=++searchRequestId;if(searchTimer)clearTimeout(searchTimer);renderCatalogSearch();if(query.length<3)return;searchTimer=setTimeout(async()=>{state.catalogSearching=true;try{const response=await fetch(`/api/academy/library-search?q=${encodeURIComponent(query)}`,{headers:authHeaders()});const data=await response.json();if(requestId!==searchRequestId)return;state.catalogMatches=response.ok?(data.paths||[]):[];state.catalogSearchResults=response.ok?(data.results||[]):[];}catch(_){if(requestId!==searchRequestId)return;state.catalogMatches=[];state.catalogSearchResults=[];}if(requestId!==searchRequestId)return;state.catalogSearching=false;renderCatalogSearch();},250);};
  const academyTrack=(type,extra={})=>{if(!access?.token)return;fetch('/api/academy/events',{method:'POST',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify({type,course_id:state.course||'',page:state.page||'',...extra})}).catch(()=>{});};
  window.academyCopyLink=async(id,section='')=>{const params=new URLSearchParams({tile:id});if(section)params.set('section',section);const url=`${location.origin}${location.pathname}#${params}`;try{await navigator.clipboard.writeText(url);state.readerNotice=section?'Ссылка на раздел скопирована.':'Ссылка на эту плитку скопирована.';}catch(_){state.readerNotice='Ссылка: '+url;}render();};
