  window.academyOpen=id=>{const course=coursesFor().find(item=>item.id===id);if(!course)return;const role=access?.role||state.role,section=new URLSearchParams(location.hash.slice(1)).get('section')||'';state.course=course.id;state.referenceView=false;state.tab=(role==='trainee'?sourceIndexesFor(course,false):sourceIndexesForAudience(course))[0]||0;state.page='course';state.test=false;state.inlineEditorPath='';history.replaceState(null,'',`#tile=${encodeURIComponent(course.id)}${section?`&section=${encodeURIComponent(section)}`:''}`);academyTrack('course_open');render();if(section)requestAnimationFrame(()=>document.getElementById(section)?.scrollIntoView({block:'start'}));else window.scrollTo(0,0);};
