    const errors=(analytics.client_errors||[]).length;
    const panel=document.createElement('section');panel.id='leader-operational-panel';panel.className='leader-results-list';panel.innerHTML=`<h2 class="leader-subhead">Практика и контроль качества</h2><div class="leader-kpis"><article><b>${assignments.length}</b><span>заданий на проверке</span></article><article><b>${analytics.opened_materials||0}</b><span>открытий материалов</span></article><article><b>${errors}</b><span>ошибок интерфейса</span></article></div><h2 class="leader-subhead">Ответы и обратная связь</h2>${assignmentRows}<h2 class="leader-subhead">Чаще открываемые материалы</h2><ul>${courseOpens}</ul>`;root.appendChild(panel);
