  function librarySaveStatus(message,isError=false){let node=document.getElementById('library-save-status');if(!node){node=document.createElement('p');node.id='library-save-status';node.className='library-save-status';node.setAttribute('role','status');node.setAttribute('aria-live','polite');document.querySelector('.curriculum-editor .editor-actions')?.insertAdjacentElement('afterend',node);}if(!node)return;node.textContent=message;node.classList.toggle('is-error',isError);}
  function incompleteLibraryTile(){return (state.libraryCatalog?.custom||[]).find(tile=>!(tile.sources||[]).length);}
  window.academyPersistLibraryCatalog=async(showConfirmation=true)=>{if(!canEditBase())return;syncLibraryEditor();const emptyTile=incompleteLibraryTile();if(emptyTile){const message=`Для плитки «${emptyTile.title||'Новая полезная тема'}» выберите хотя бы один материал или удалите плитку.`;state.libraryError=message;librarySaveStatus(message,true);return;}state.librarySaving=true;state.libraryError='';librarySaveStatus('Сохраняю изменения…');try{const response=await fetch('/api/academy/library-catalog',{method:'POST',headers:{'Content-Type':'application/json',...authHeaders()},body:JSON.stringify(state.libraryCatalog)});if(!response.ok)throw new Error(await academySaveError(response,'Не удалось сохранить каталог.'));const data=await response.json();state.libraryCatalog=data.catalog||state.libraryCatalog;librarySaveStatus(showConfirmation?'Сохранено в общей базе.':'Изменения сохранены.');}catch(error){const message=error.message||'Не удалось сохранить каталог.';state.libraryError=message;librarySaveStatus(message,true);}state.librarySaving=false;};
  window.academyQueueLibrarySave=()=>{if(!canEditBase())return;syncLibraryEditor();const emptyTile=incompleteLibraryTile();if(emptyTile){librarySaveStatus(`Плитка «${emptyTile.title||'Новая полезная тема'}» ждёт выбора материала.`,true);return;}if(librarySaveTimer)clearTimeout(librarySaveTimer);librarySaveStatus('Сохраняю изменения…');librarySaveTimer=setTimeout(()=>window.academyPersistLibraryCatalog(false),450);};
  window.academyRemoveLibraryTile=(id,custom)=>{syncLibraryEditor();if(custom)state.libraryCatalog.custom=state.libraryCatalog.custom.filter(tile=>tile.id!==id);else if(!state.libraryCatalog.hidden.includes(id))state.libraryCatalog.hidden.push(id);render();window.academyPersistLibraryCatalog(true);};
